import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

export default function Chatbot() {
  const [open, setOpen] = useState(false);
  const [messages, setMessages] = useState([
    { from: "bot", text: "Hi! Try saying: events, login, register" }
  ]);
  const [text, setText] = useState("");

  const navigate = useNavigate();

  function handleButtonClick(btn) {
    // Example format: "navigate:/events|Events"
    if (btn.startsWith("navigate:")) {
      const [command, label] = btn.split("|");
      const path = command.replace("navigate:", "");

      navigate(path);  // ← WORKS 100%
      return;
    }

    send(btn);
  }

  async function send(msg) {
    if (!msg.trim()) return;

    setMessages((prev) => [...prev, { from: "user", text: msg }]);
    setText("");

    try {
      const res = await fetch(
        (process.env.REACT_APP_API || "http://localhost:4000") + "/api/chat",
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ message: msg }),
        }
      );

      const data = await res.json();

      setMessages((prev) => [
        ...prev,
        {
          from: "bot",
          text: data.reply,
          buttons: data.buttons || []
        }
      ]);
    } catch (err) {
      setMessages((prev) => [
        ...prev,
        { from: "bot", text: "Server unavailable." }
      ]);
    }
  }

  return (
    <div className="chatbot">
      <button className="chat-toggle" onClick={() => setOpen(!open)}>
        {open ? "Close Chat" : "Chat with us"}
      </button>

      {open && (
        <div className="chat-window">
          <div className="messages">
            {messages.map((m, i) => (
              <div key={`msg-${i}`} className={`msg ${m.from}`}>
                <p>{m.text}</p>

                {Array.isArray(m.buttons) && m.buttons.length > 0 && (
                  <div className="buttons" key={`btns-${i}`}>
                    {m.buttons.map((b, bi) => {
                      const [cmd, label] = b.split("|");
                      return (
                        <button
                          key={`btn-${i}-${bi}`}
                          onClick={() => handleButtonClick(b)}
                        >
                          {label}
                        </button>
                      );
                    })}
                  </div>
                )}
              </div>
            ))}
          </div>

          <div className="chat-input">
            <input
              value={text}
              onChange={(e) => setText(e.target.value)}
              placeholder="Type a message"
              onKeyDown={(e) => e.key === "Enter" && send(text)}
            />
            <button onClick={() => send(text)}>Send</button>
          </div>
        </div>
      )}
    </div>
  );
}
